START TRANSACTION;

-- ---------------------------------------------------------------- id 92 F14
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 92,'proposito','Contribuir al fortalecimiento de los procesos artísticos y culturales del municipio de Carepa mediante el diseño, desarrollo y acompañamiento de actividades formativas, creativas y comunitarias en los distintos programas culturales adscritos a la Secretaría de Educación y Cultura, como son danza bullerengue, danza baile moderno, danza urbana, música folclórica, danza folclórica, artes plásticas y pinturas, música vallenata, teatro y títeres, promoviendo la participación y la convivencia ciudadana, y el desarrollo del talento local.',140 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=92 AND seccion='proposito');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 92,'funciones','["Diseñar y ejecutar procesos formativos, talleres y actividades artísticas y culturales, orientados al desarrollo de habilidades, y la apropiación cultural de la comunidad.", "Brindar capacitación, orientación y acompañamiento a los participantes, garantizando metodologías adecuadas para el aprendizaje y la práctica de las diferentes expresiones artísticas.", "Organizar, apoyar y participar en eventos, presentaciones o actividades culturales, con el fin de estimular la participación ciudadana y visibilizar el talento local.", "Realizar seguimiento y evaluar el impacto de las actividades desarrolladas, identificando avances, necesidades de mejora y resultados en el fortalecimiento cultural y la convivencia.", "Mantener una comunicación permanente con la comunidad y los actores culturales, promoviendo el acceso, la participación y el interés en las ofertas artístico-culturales.", "Asistir a reuniones, encuentros y espacios de articulación cultural a nivel municipal, departamental o nacional, cuando sea requerido por su jefe inmediato.", "Acompañar las actividades institucionales de la Administración Municipal, cuando sean solicitadas por el jefe inmediato o las directivas de la Secretaría.", "Coordinar acciones con otros monitores y personal de la Casa de la Cultura, para asegurar la adecuada planificación, ejecución y evaluación de las actividades programadas.", "Informar oportunamente al supervisor sobre dificultades, novedades o situaciones que puedan afectar el desarrollo de las actividades o el cumplimiento de sus funciones.", "Apoyar la realización de fiestas, celebraciones y eventos relevantes del municipio, cuando sean requeridos por la Secretaría de Educación y Cultura o la Administración Municipal.", "Promocionar y difundir la oferta artística y cultural de la Casa de la Cultura, incentivando la participación de niños, jóvenes, adultos y comunidad en general.", "Colaborar en la atención al público, inscripción y gestión de participantes, asegurando un servicio adecuado y una organización eficiente de los grupos y actividades.", "Elaborar y presentar informes periódicos sobre las actividades realizadas, el avance de los procesos y los resultados obtenidos.", "Realizar las demás actividades que sean asignadas por su jefe inmediato, relacionadas con la dinámica cultural y el cumplimiento de los objetivos institucionales."]',141 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=92 AND seccion='funciones');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 92,'contribuciones','["Asegurar la formación artística y cultural de los participantes", "Garantizar la correcta planeación y organización de las actividades culturales.", "Promover la participación ciudadana y la apropiación cultural", "Contribuir al fortalecimiento de la convivencia y el tejido social."]',142 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=92 AND seccion='contribuciones');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 92,'conocimientos','["Manejo de herramientas Ofimáticas, (Procesadores de texto, Word Excel, Power Point).", "Sistema de Gestión de calidad aplicable dentro del Municipio.", "Fundamentos de pedagogía y didáctica artística, Técnicas básicas de planificación, ejecución y evaluación de actividades culturales.", "Principios generales de las artes y la cultura.", "Normatividad básica en materia cultural.", "Metodologías de trabajo comunitario y participación ciudadana.", "Habilidades de comunicación asertiva y atención al público.", "Técnicas de organización de eventos y actividades culturales."]',143 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=92 AND seccion='conocimientos');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 92,'competencias','{"comunes": ["Aprendizaje continúo", "Orientación a resultados", "Orientación al usuario y al ciudadano", "Compromiso con la organización", "Trabajo en equipo", "Adaptación al cambio"], "nivel": ["Confiabilidad Técnica", "Disciplina", "Responsabilidad"]}',144 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=92 AND seccion='competencias');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 92,'requisitos_estudio','ESTUDIOS Título de formación técnica o tecnólogo del núcleo básico del conocimiento en: Ciencias de la Educación, Bellas Artes. Equivalencias: De conformidad con el Decreto ley 785 de 2005, Artículo 25 Numeral 25.2.3 Un (1) año de educación superior por un (1) año de experiencia y viceversa, o por seis (6) meses de experiencia relacionada y curso específico de mínimo sesenta (60) horas de duración y viceversa, siempre y cuando se acredite diploma de bachiller para ambos casos.',145 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=92 AND seccion='requisitos_estudio');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 92,'requisitos_experiencia','EXPERIENCIA Un (1) año de experiencia relacionada',146 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=92 AND seccion='requisitos_experiencia');

-- ---------------------------------------------------------------- id 95 F21
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 95,'proposito','Desarrollar, las actividades tendientes al cumplimiento de las normas vigentes en materia de tránsito en el territorio de su jurisdicción con el fin de disminuir el índice de accidentalidad.',140 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=95 AND seccion='proposito');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 95,'funciones','["Verificar el cumplimiento de las normas del Código Nacional de Tránsito y demás disposiciones sobre la materia, para el correcto desarrollo del flujo vehicular.", "Controlar el tránsito en las vías públicas municipales y nacionales, con el propósito de disminuir la accidentalidad vial.", "Apoyar las Capacitaciones conductores, propietarios de vehículos, peatones, educadores y estudiantes en normas de tránsito y seguridad vial, para una mejor aplicación y promoción de las mismas.", "Elaborar al conductor infractor la Orden de Comparendo Nacional o diligenciar el informe de accidente cuando sea necesario.", "Inmovilizar vehículos en cumplimiento a órdenes de autoridad competente cuando las normas de tránsito o transporte lo faculten y colocarlos a disposición de la jurisdicción correspondiente, para la investigación a que haya lugar.", "Apoyar a los organismos municipales y entidades que lo requieran en la organización vehicular y peatonal durante fiestas y eventos culturales, deportivos y catastróficos, con el fin de que estos tengan un correcto funcionamiento.", "Trasladar y/o velar porque a conductores en estado de embriaguez o cuando la situación lo amerite, se les practique el examen de alcoholemia o droga, para que sirva como base o prueba en el análisis de una infracción o en el desarrollo de una investigación que aclare la causa de un accidente.", "Coadyuvar en la señalización de las diferentes vías urbanas municipales, para una correcta organización vial.", "Auxiliar a Conductores con percance en las carreteras, al igual que conducir vehículos, cuando se requiera, como apoyo al usuario y a la institución.", "Realizar labores de apoyo a los diferentes grupos de trabajo dentro de la Secretaría.", "Promover y desarrollar la cultura ciudadana, enfatizando en aspectos como tolerancia, democracia y participación en los habitantes del Municipio.", "Cuidar y salvaguardar los bienes y equipos que la Administración Municipal entregue a su cargo para el cabal ejercicio de sus funciones.", "Apoyar el control de la ocupación y uso del espacio público de conformidad con los programas y planes trazados por la administración municipal", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia."]',141 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=95 AND seccion='funciones');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 95,'contribuciones','["Reducción del índice de infracciones.", "Disminución de la accidentalidad vial.", "Mejoramiento del flujo vehicular y peatonal en el municipio."]',142 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=95 AND seccion='contribuciones');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 95,'conocimientos','["Normas de tránsito y transporte.", "Relaciones humanas y primeros auxilios.", "Mecánica automotriz y Diesel.", "Técnicas de conducción.", "Ubicación geográfica del municipio.", "Sistema de Gestión de calidad aplicable dentro del Municipio."]',143 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=95 AND seccion='conocimientos');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 95,'competencias','{"comunes": ["Aprendizaje continúo", "Orientación a resultados", "Orientación al usuario y al ciudadano", "Compromiso con la organización", "Trabajo en equipo", "Adaptación al cambio"], "nivel": ["Confiabilidad Técnica", "Disciplina", "Responsabilidad"]}',144 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=95 AND seccion='competencias');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 95,'requisitos_estudio','ESTUDIOS Título de formación técnica en cualquier área del conocimiento y/o Poseer diploma de bachiller, Cursar y aprobar el programa de capacitación (cátedra de formación e intensidad mínima establecida por la autoridad competente). Poseer licencia de conducción de acuerdo a la normativa vigente (ley 1310 de 2009).',145 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=95 AND seccion='requisitos_estudio');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 95,'requisitos_experiencia','EXPERIENCIA Seis (06) meses de experiencia relacionada',146 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=95 AND seccion='requisitos_experiencia');

