INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 130,'proposito','Prestar apoyo técnico y administrativo en los procesos y acciones de vigilancia y control del funcionamiento del régimen subsidiado y contributivo en salud en el municipio',140 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=130 AND seccion='proposito');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 130,'funciones','["Apoyar en la afiliación al potencial priorizado a ser beneficiario del Plan obligatorio de salud del régimen subsidiado.", "Apoyar la elaboración de forma mensual procesos de actualización y depuración de las bases de datos de la población asegurada del Municipio de Carepa.", "Acompañar la implementación y ejecución de estrategias para la identificación y localización de las personas que presentan inconsistencias en su afiliación en salud y posteriormente acompañar el proceso para subsanarlas.", "Realizar acciones para apoyar la garantía de prestación de servicios de salud para la población pobre y vulnerable del Municipio.", "Apoyar la actualización y seguimiento del listado de los prestadores de servicio de salud, con el fin de contar con un registro de IPS habilitadas que este actualizado.", "Apoyar las visitas de verificación a fin de constatar que las IPS que funcionan en el Municipio, están prestando los servicios que efectivamente declararon ante la SSSA.", "Apoyar en la verificación de las IPS que llegan al Municipio a realizar jornadas de promoción y prevención de la salud, con el fin de garantizar que cumplen con la habilitación ante la SSSA.", "Apoyar el proceso de vigilancia a las EPS e IPS presentes en el municipio con el fin de verificar que las oficinas de atención al usuario funcionan de acuerdo a la normatividad vigente.", "Participar de jornadas de atención a la comunidad extramurales en articulación con otras dependencias con fin de fortalecer las acciones para el aseguramiento y el acceso a los servicios de salud de la población.", "Apoyar la implementación de acciones orientadas al mejoramiento de la accesibilidad de los servicios de salud por parte de los usuarios.", "Apoyar la implementación de acciones orientadas al mejoramiento de la calidad en la atención en salud por parte de cada uno de los prestadores del servicio en la localidad.", "Presentar, informes de gestión para hacer seguimiento y evaluación a los objetivos trazados por la dependencia.", "Adoptar las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia.", "Apoyar al jefe de la dependencia en la elaboración de los planes de acción.", "Las demás que sean asignadas por su superior inmediato."]',141 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=130 AND seccion='funciones');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 130,'contribuciones','["Los habitantes del municipio acceden a los servicios de salud que se les prestan con calidad.", "Población afiliada al régimen subsidiado.", "Asignación eficiente y oportuna de los recursos del régimen subsidiado.", "Proyectos de interventoría aplicados a la prestación de los servicios por parte de las EPS.", "Acciones de vigilancia y control desarrollados en lo referente al aseguramiento y la prestación de servicios."]',142 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=130 AND seccion='contribuciones');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 130,'conocimientos','["Normatividad legal en relación con el régimen subsidiado", "Interventoría a la contratación del régimen subsidiado", "Manejo de herramientas Ofimáticas, (Procesadores de texto, Word, Excel, Power Point).", "Sistema de Gestión de calidad aplicable dentro del Municipio.", "Contratación e interventorías en servicios de salud.", "Metodologías y presentación de proyectos para el sector público y privado"]',143 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=130 AND seccion='conocimientos');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 130,'competencias','{"comunes": ["Aprendizaje continúo", "Orientación a resultados", "Orientación al usuario y al ciudadano", "Compromiso con la organización", "Trabajo en equipo", "Adaptación al cambio"], "nivel": ["Confiabilidad Técnica", "Disciplina", "Responsabilidad"]}',144 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=130 AND seccion='competencias');
INSERT INTO cargos_manual_detalle (cargo_manual_id,seccion,contenido,orden) SELECT 130,'requisitos_estudio','ESTUDIOS Técnico o tecnólogo en diciplina académica del NBC: Ciencias Sociales y Humanas, Sociología, Trabajo Social y Afines, Ciencias de la salud.',145 FROM (SELECT 1 AS one) d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=130 AND seccion='requisitos_estudio');
