-- VERIFICACIONES
-- NOTA: ids 92 y 95 YA tenían las 7 secciones (seed 'Sincronizacion inicial
-- manual funciones 2026-07-17'); sus INSERT son no-ops por guardia NOT EXISTS.
-- Solo id 130 inserta 7 filas nuevas. Anomalías preexistentes de 92/95 —
-- FUERA DE ALCANCE aqui: competencias con string concatenado (patron R-2,
-- van al lote R-2/M013) y requisitos sin prefijo ESTUDIOS/EXPERIENCIA
-- (normalizacion de formato posterior).
-- Esperado: los 3 cargos con 7 secciones cubiertas al terminar.
SELECT cargo_manual_id, COUNT(*) AS secciones_esperadas_7,
       GROUP_CONCAT(seccion ORDER BY orden) AS secciones
 FROM cargos_manual_detalle WHERE cargo_manual_id IN (92,95,130) GROUP BY cargo_manual_id;
SELECT COUNT(*) AS json_invalidos_nuevos_esperado_0 FROM cargos_manual_detalle
 WHERE cargo_manual_id IN (92,95,130) AND creado_en >= CURDATE()
   AND seccion IN ('funciones','contribuciones','conocimientos','competencias')
   AND JSON_VALID(contenido)=0;

COMMIT;

